import os
import hashlib
import hmac
import time
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = os.environ.get('DB_PATH', '/data/inventory.db')
app.config['API_SECRET'] = os.environ.get('API_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Token')
        timestamp = request.headers.get('X-Timestamp')
        if not token or not timestamp:
            return jsonify({'error': 'unauthorized'}), 401
        try:
            ts = int(timestamp)
            if abs(time.time() - ts) > 300:
                return jsonify({'error': 'expired'}), 401
        except ValueError:
            return jsonify({'error': 'invalid timestamp'}), 401
        expected = hmac.new(app.config['API_SECRET'].encode(),
                           timestamp.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(token, expected):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/inventory/search', methods=['GET'])
@require_auth
def search_inventory():
    """Search inventory items by various criteria."""
    warehouse = request.args.get('warehouse', '')
    category = request.args.get('category', '')
    min_qty = request.args.get('min_qty', '0')
    sort_field = request.args.get('sort', 'item_name')

    # Build base query with parameterized values
    conditions = []
    params = []

    if warehouse:
        conditions.append('warehouse_id = ?')
        params.append(warehouse)
    if category:
        conditions.append('category = ?')
        params.append(category)
    if min_qty:
        conditions.append('quantity >= ?')
        params.append(int(min_qty))

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Sort field validated against allowed columns
    allowed_sorts = ['item_name', 'quantity', 'warehouse_id', 'category', 'updated_at']
    if sort_field not in allowed_sorts:
        sort_field = 'item_name'

    query = f"SELECT item_id, item_name, category, quantity, warehouse_id, updated_at FROM inventory WHERE {where_clause} ORDER BY {sort_field} LIMIT 100"

    db = get_db()
    results = db.execute(query, params).fetchall()
    return jsonify([dict(row) for row in results])

@app.route('/api/v1/inventory/report', methods=['POST'])
@require_auth
def generate_report():
    """Generate inventory report with custom grouping."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    group_by = data.get('group_by', 'category')
    date_from = data.get('date_from', '')
    date_to = data.get('date_to', '')
    warehouse_filter = data.get('warehouse', '')

    # Construct aggregation query
    base_conditions = []
    params = []

    if date_from:
        base_conditions.append('updated_at >= ?')
        params.append(date_from)
    if date_to:
        base_conditions.append('updated_at <= ?')
        params.append(date_to)
    if warehouse_filter:
        base_conditions.append('warehouse_id = ?')
        params.append(warehouse_filter)

    where_clause = ' WHERE ' + ' AND '.join(base_conditions) if base_conditions else ''

    # group_by is user-controlled - used directly in query
    query = f"SELECT {group_by}, COUNT(*) as item_count, SUM(quantity) as total_qty FROM inventory{where_clause} GROUP BY {group_by}"

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        return jsonify({'report': [dict(row) for row in results]})
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v1/inventory/bulk-update', methods=['PUT'])
@require_auth
def bulk_update():
    """Bulk update inventory quantities."""
    data = request.get_json()
    if not data or 'updates' not in data:
        return jsonify({'error': 'invalid request'}), 400

    db = get_db()
    updated = 0
    for item in data['updates']:
        item_id = item.get('item_id')
        new_qty = item.get('quantity')
        if item_id and new_qty is not None:
            db.execute('UPDATE inventory SET quantity = ?, updated_at = datetime("now") WHERE item_id = ?',
                      (int(new_qty), item_id))
            updated += 1
    db.commit()
    return jsonify({'updated': updated})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
